script:
const phanHe = ctx.val('phan_he', 'maintenance').trim().toLowerCase() || 'maintenance';
const targetUrl = `https://tasks.zuizui.io/${phanHe}/create/list`;
const keyword = ctx.val('tu_khoa', 'test').trim();

await step('Mở danh sách phiếu ' + phanHe, async () => {
  if (!page.url().includes(`/${phanHe}/`)) {
    await page.goto(targetUrl, { waitUntil: 'domcontentloaded' });
  }
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  await page.getByRole('textbox', { name: 'Nhập tên phiếu để tìm' }).waitFor({ timeout: 20000 });
});

await step('Chuyển đổi các tab danh sách', async () => {
  const tabAssigned = page.getByText(/Tôi phụ trách\/Hỗ trợ/).first();
  if (await tabAssigned.isVisible().catch(() => false)) {
    await tabAssigned.click();
    await page.waitForTimeout(500);
  }
  const tabPending = page.getByText('Chưa hoàn tất', { exact: true }).first();
  if (await tabPending.isVisible().catch(() => false)) {
    await tabPending.click();
    await page.waitForTimeout(500);
  }
  const tabAll = page.getByText('Tất cả', { exact: true }).first();
  await tabAll.waitFor({ timeout: 10000 });
  await tabAll.click();
  await page.waitForLoadState('networkidle', { timeout: 15000 }).catch(() => {});
});

await step('Tìm kiếm phiếu theo từ khóa', async () => {
  const searchBox = page.getByRole('textbox', { name: 'Nhập tên phiếu để tìm' });
  await searchBox.click();
  await searchBox.fill(keyword);
  const searchBtn = page.locator('.hrv-next-input-add-on.hrv-next-input__add-on--after > span > svg').first();
  if (await searchBtn.isVisible().catch(() => false)) {
    await searchBtn.click();
  } else {
    await searchBox.press('Enter');
  }
  await page.waitForLoadState('networkidle', { timeout: 15000 }).catch(() => {});
  ctx.log('Đã tìm kiếm với từ khóa: ' + keyword);
});

await step('Kiểm tra nút Xuất dữ liệu', async () => {
  const exportBtn = page.getByRole('button', { name: 'Xuất dữ liệu' });
  await exportBtn.waitFor({ timeout: 10000 });
  await exportBtn.click();
  const waitingMsg = page.getByText(/Vui lòng đợi trong giây lát|Xuất dữ liệu/i).first();
  await waitingMsg.waitFor({ timeout: 10000 });
  ctx.log('Đã kích hoạt Xuất dữ liệu thành công.');
});
